import{_ as i,a0 as n,w as o,s as r,ao as c,I as s,x as e,a1 as a,A as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"一些 Shell 脚本的基本概念 | LCTT x X-CMD","titleTemplate":false,"description":"一些 Shell 脚本的基本概念 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一些 Shell 脚本的基本概念 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一些 Shell 脚本的基本概念 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220524 The Basic Concepts of Shell Scripting","title":"一些 Shell 脚本的基本概念","tag":"202209","desc":""},"relativePath":"202209/20220524 The Basic Concepts of Shell Scripting.md","filePath":"[post].md"}'),p={name:"202209/20220524 The Basic Concepts of Shell Scripting.md"};function h(g,t,f,x,y,b){const l=n("Link");return o(),r("div",null,[t[15]||(t[15]=c(`<h1 id="一些-shell-脚本的基本概念" tabindex="-1">一些 Shell 脚本的基本概念 <a class="header-anchor" href="#一些-shell-脚本的基本概念" aria-label="Permalink to “一些 Shell 脚本的基本概念”">​</a></h1><blockquote><p>如果你希望自动执行常规任务并使你的生活更轻松，那么使用 Shell 脚本是一个很好的选择。本文将向你介绍一些基本概念，这些概念将帮助你编写高效的 Shell 脚本。</p></blockquote><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Shell-scripting.jpg" alt="Shell-scripting"></p><p>Shell 脚本是一种被设计用来运行命令行解释器 UNIX Shell 的计算机程序。Shell 脚本的各类变种被视作脚本语言。Shell 脚本执行的典型操作包括文件操作、程序执行和文本打印。设置环境、运行程序并执行任何必要的清理或日志记录的脚本称为封装。</p><h3 id="识别-shell-命令提示符" tabindex="-1">识别 Shell 命令提示符 <a class="header-anchor" href="#识别-shell-命令提示符" aria-label="Permalink to “识别 Shell 命令提示符”">​</a></h3><p>你可以通过查看终端窗口中的提示符符号来识别 Linux 系统的计算机上的 Shell 命令提示符的用户是普通用户还是超级用户。<code>#</code> 符号用于超级用户，<code>$</code> 符号用于具有标准权限的用户。</p><h3 id="基本命令" tabindex="-1">基本命令 <a class="header-anchor" href="#基本命令" aria-label="Permalink to “基本命令”">​</a></h3><p>脚本附带了很多可以在终端窗口上执行的、用以管理您的计算机的命令。每个命令的详细信息可以在该命令附带的使用手册中找到。你可以使用如下命令来查看手册：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man &lt;command&gt;</span></span></code></pre></div><p>一些常用的命令有：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>date # 显示当前日期和时间</span></span>
<span class="line"><span>cal # 显示当前月份日历</span></span>
<span class="line"><span>df # 显示磁盘使用情况</span></span>
<span class="line"><span>free # 显示内存使用情况</span></span>
<span class="line"><span>ls # 列出文件和目录</span></span>
<span class="line"><span>mkdir # 创建目录</span></span></code></pre></div><p>每个命令都附带了几个可以一起使用的选项。你可以参考使用手册以了解更多的细节。<code>man date</code> 的输出如图 1 所示。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-1-Manual-of-date-command.jpg" alt="Figure 1: Manual of date command"></p><h3 id="重定向操作符" tabindex="-1">重定向操作符 <a class="header-anchor" href="#重定向操作符" aria-label="Permalink to “重定向操作符”">​</a></h3><p>当你希望捕获文件中的命令输出或重定向到文件时，可以使用重定向操作符。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ls -l /usr/bin &gt;file</code></td><td style="text-align:left;">默认标准输出到文件</td></tr><tr><td style="text-align:left;"><code>ls -l /usr/bin 2&gt;file</code></td><td style="text-align:left;">重定向标准错误到文件</td></tr><tr><td style="text-align:left;"><code>ls -l /usr/bin &gt; ls-output 2&gt;&amp;1</code></td><td style="text-align:left;">重定向标准错误和标准输出到文件</td></tr><tr><td style="text-align:left;"><code>ls -l /usr/bin &amp;&gt; ls-output</code></td><td style="text-align:left;">重定向标准错误和标准输出到文件</td></tr><tr><td style="text-align:left;"><code>ls -l /usr/bin 2&gt; /dev/null</code></td><td style="text-align:left;">写入 <code>/dev/null</code>，丢弃输出</td></tr></tbody></table></div><h3 id="大括号扩展" tabindex="-1">大括号扩展 <a class="header-anchor" href="#大括号扩展" aria-label="Permalink to “大括号扩展”">​</a></h3><p>大括号扩展是 UNIX 提供的强大选项之一。它有助于在一行指令中使用最少的命令完成大量操作。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$echo Front-{A,B,C}-Back</span></span>
<span class="line"><span>Front-A-Back, Front-B-Back, Front-C-Back</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$echo {Z..A}</span></span>
<span class="line"><span>Z Y X W V U T S R Q P O N M L K J I H G F E D C B A</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mkdir {2009..2011}-0{1..9} {2009..2011}-{10..12}</span></span></code></pre></div><p>这条命令会为 2009 到 2011 年里的每个月建立一个目录。</p><h3 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to “环境变量”">​</a></h3><p>环境变量是一个动态命名的值，它可以影响计算机上运行的进程的行为方式。此变量是进程运行环境的一部分。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>printenv</code></td><td style="text-align:left;">打印出所有环境变量的值。</td></tr><tr><td style="text-align:left;"><code>set</code></td><td style="text-align:left;">设置 Shell 选项</td></tr><tr><td style="text-align:left;"><code>export</code></td><td style="text-align:left;">导出环境到随后执行的程序</td></tr><tr><td style="text-align:left;"><code>alias</code></td><td style="text-align:left;">为命令创建别名</td></tr></tbody></table></div><h3 id="网络命令" tabindex="-1">网络命令 <a class="header-anchor" href="#网络命令" aria-label="Permalink to “网络命令”">​</a></h3><p>网络命令对于排查网络问题和检查连接到客户机的特定端口非常有用。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ping</code></td><td style="text-align:left;">发送 ICMP（网际网路控制讯息协定）数据包</td></tr><tr><td style="text-align:left;"><code>traceroute</code></td><td style="text-align:left;">打印数据包在网络中的路径</td></tr><tr><td style="text-align:left;"><code>netstat</code></td><td style="text-align:left;">打印网络连接信息、路由表、接口数据</td></tr><tr><td style="text-align:left;"><code>ftp</code>/<code>lftp</code></td><td style="text-align:left;">互联网文件传输程序</td></tr><tr><td style="text-align:left;"><code>wget</code></td><td style="text-align:left;">非交互式网络下载器</td></tr><tr><td style="text-align:left;"><code>ssh</code></td><td style="text-align:left;">OpenSSH SSH 客户端 （远程登录程序）</td></tr><tr><td style="text-align:left;"><code>scp</code></td><td style="text-align:left;">安全拷贝</td></tr><tr><td style="text-align:left;"><code>sftp</code></td><td style="text-align:left;">安全文件传输程序</td></tr></tbody></table></div><h3 id="grep-命令" tabindex="-1">grep 命令 <a class="header-anchor" href="#grep-命令" aria-label="Permalink to “grep 命令”">​</a></h3><p><code>grep</code> 命令用于查找系统和日志中的错误。它是 Shell 拥有的强大工具之一。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>grep -h &#39;.zip&#39; file.list</code></td><td style="text-align:left;"><code>.</code> 表示任意字符</td></tr><tr><td style="text-align:left;"><code>grep -h &#39;^zip&#39; file.list</code></td><td style="text-align:left;">以 <code>zip</code> 开头</td></tr><tr><td style="text-align:left;"><code>grep -h &#39;zip$&#39; file.list</code></td><td style="text-align:left;">以 <code>zip</code> 结尾</td></tr><tr><td style="text-align:left;"><code>grep -h &#39;^zip$&#39; file.list</code></td><td style="text-align:left;">只含有 <code>zip</code></td></tr><tr><td style="text-align:left;"><code>grep -h &#39;[^bz]zip&#39; file.list</code></td><td style="text-align:left;">不含 <code>b</code> 和 <code>z</code></td></tr><tr><td style="text-align:left;"><code>grep -h &#39;^[A-Za-z0-9]&#39; file.list</code></td><td style="text-align:left;">所有文件名有效的文件</td></tr></tbody></table></div><h3 id="量词" tabindex="-1">量词 <a class="header-anchor" href="#量词" aria-label="Permalink to “量词”">​</a></h3><p>下面是一些量词的例子：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>?</code></td><td style="text-align:left;">匹配出现 0 次或 1 次的元素</td></tr><tr><td style="text-align:left;"><code>*</code></td><td style="text-align:left;">匹配出现 0 次或多次的元素</td></tr><tr><td style="text-align:left;"><code>+</code></td><td style="text-align:left;">匹配出现 1 次或多次的元素</td></tr><tr><td style="text-align:left;"><code>{}</code></td><td style="text-align:left;">匹配出现特定次数的元素</td></tr></tbody></table></div><h3 id="文本处理" tabindex="-1">文本处理 <a class="header-anchor" href="#文本处理" aria-label="Permalink to “文本处理”">​</a></h3><p>文本处理是当今 IT 世界中的另一项重要任务。程序员和管理员可以使用这些命令来切片、剪切和处理文本。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>cat -A $FILE</code></td><td style="text-align:left;">显示 <code>$FILE</code> 文件的所有内容</td></tr><tr><td style="text-align:left;"><code>sort file1.txt file2.txt file3.txt &gt; final_sorted_list.txt</code></td><td style="text-align:left;">一次性将所有文件排序</td></tr><tr><td style="text-align:left;">\`ls - l</td><td style="text-align:left;">sort -nr -k 5\`</td></tr><tr><td style="text-align:left;"><code>sort --key=1,1 --key=2n distor.txt</code></td><td style="text-align:left;">对第 1 列进行排序（默认按字母表顺序），对第 2 列进行数值排序</td></tr><tr><td style="text-align:left;">\`sort foo.txt</td><td style="text-align:left;">uniq -c\`</td></tr><tr><td style="text-align:left;"><code>cut -f 3 distro.txt</code></td><td style="text-align:left;">剪切第 3 列</td></tr><tr><td style="text-align:left;"><code>cut -c 7-10</code></td><td style="text-align:left;">剪切 7 - 10 字符</td></tr><tr><td style="text-align:left;"><code>cut -d &#39;:&#39; -f 1 /etc/password</code></td><td style="text-align:left;">分隔符 <code>:</code></td></tr><tr><td style="text-align:left;"><code>sort -k 3.7nbr -k 3.1nbr -k 3.4nbr distro.txt</code></td><td style="text-align:left;">按第 3 列第 7 个字符、第 3 列第 1 个字符和第 3 列第 4 个字符排序</td></tr><tr><td style="text-align:left;"><code>paste file1.txt file2.txt &gt; newfile.txt</code></td><td style="text-align:left;">合并两个文件</td></tr><tr><td style="text-align:left;"><code>join file1.txt file2.txt</code></td><td style="text-align:left;">按公共字段连接两个文件</td></tr></tbody></table></div><h3 id="窍门和技巧" tabindex="-1">窍门和技巧 <a class="header-anchor" href="#窍门和技巧" aria-label="Permalink to “窍门和技巧”">​</a></h3><p>在 Linux 中，我们可以通过使用简单的命令或控制选项返回到命令的历史记录。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>clear</code></td><td style="text-align:left;">清空屏幕</td></tr><tr><td style="text-align:left;"><code>history</code></td><td style="text-align:left;">查看保存命令的历史记录</td></tr><tr><td style="text-align:left;"><code>script filename</code></td><td style="text-align:left;">捕获文件中的所有命令执行</td></tr></tbody></table></div><p>一些历史命令的技巧：</p><ul><li><code>CTRL + R</code>： 搜索命令历史</li><li><code>!!number</code>：执行编号为 <code>number</code> 的命令</li><li><code>!!</code> ：执行上一条命令</li><li><code>!?string</code> : 执行包含 <code>string</code> 的上一条命令</li><li><code>!string</code>：执行以 <code>string</code> 开始的上一条命令</li><li><code>export HISTCONTROL=ignoredups</code>： 忽略重复条目</li><li><code>export HISTSIZE=10000</code>：设置存储的历史行数</li></ul><p>随着你对 Linux 命令逐渐熟悉，你将能够编写封装脚本。所有手动任务，如定期备份、清理文件、监控系统使用情况等，都可以使用脚本自动完成。在学习高级概念之前，本文将帮助您开始编写脚本。</p><hr>`,44)),s("p",null,[t[1]||(t[1]=e("via: ",-1)),a(l,{href:"https://www.opensourceforu.com/2022/05/the-basic-concepts-of-shell-scripting/"},{default:d(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/05/the-basic-concepts-of-shell-scripting/",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=e("作者：",-1)),a(l,{href:"https://www.opensourceforu.com/author/sathyanarayanan-thangavelu/"},{default:d(()=>[...t[2]||(t[2]=[e("Sathyanarayanan Thangavelu",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),a(l,{href:"https://github.com/lkxed"},{default:d(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),a(l,{href:"https://github.com/FYJNEVERFOLLOWS"},{default:d(()=>[...t[4]||(t[4]=[e("FYJNEVERFOLLOWS",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),a(l,{href:"https://github.com/wxy"},{default:d(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=e("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),a(l,{href:"https://linux.cn/"},{default:d(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const S=i(p,[["render",h]]);export{m as __pageData,S as default};
